export const cases=[
 {id:'pressure',label:'Presión baja',axis:'A',hint:'Compara PS / I0.4 y las dos salidas en el mismo scan.',explain:'La presión cayó de 4 a 0 bar: PS pasó a 0 y P01 retiró RUN y ambas salidas inmediatamente. No fue necesario esperar el timeout de llegada.'},
 {id:'jamA',label:'Cilindro A atascado',axis:'A',hint:'Busca si A llegó a 100 mm antes del timeout.',explain:'A quedó a mitad de carrera con PS=1 y YA=1. a1 nunca confirmó el extremo; después del límite de carrera, la red 06 retiró las salidas. Mientras siga el atasco, A tampoco podrá retornar aunque YA caiga.'},
 {id:'jamB',label:'Cilindro B atascado',axis:'B',hint:'Compara la posición de B con YB y b1 antes del fallo.',explain:'B dejó de avanzar a mitad de carrera aunque YB=1 y PS=1. b1 permaneció en 0; la red 07 disparó el timeout. Al retirar YA, A queda libre para retornar con aire; B sigue bloqueado.'},
 {id:'i1',label:'Sensor a1 desconectado',axis:'A',hint:'¿A alcanzó 100 mm mientras I0.1 seguía en 0?',explain:'A llegó físicamente al extremo, pero a1 / I0.1 siguió en 0. La red 06 generó el mismo timeout que un atasco. La posición permite distinguirlos en este simulador.'},
 {id:'i3',label:'Sensor b1 desconectado',axis:'B',hint:'¿B alcanzó 100 mm mientras I0.3 seguía en 0?',explain:'B llegó al extremo, pero b1 / I0.3 no lo confirmó. La red 07 retiró ambas salidas por timeout. El movimiento completo descarta un atasco en este reto.'}
];
export function startDiagnostic(s,random=Math.random){const item=cases[Math.min(cases.length-1,Math.floor(random()*cases.length))];s.diagnostic={id:item.id,injected:false,revealed:false,solved:false,hints:0,attempts:0,feedback:''};return s.diagnostic;}
export function injectDiagnostic(s){const d=s.diagnostic;if(!d||d.injected)return;const item=cases.find(c=>c.id===d.id);if((item.axis==='A'?s.x:s.y)<.35)return;d.injected=true;d.time=s.time;if(d.id==='pressure')s.lowPressure=true;else if(d.id.startsWith('jam'))s[d.id]=true;else s.disabledSensors[d.id]=true;}
export function answerDiagnostic(s,answer){const d=s.diagnostic;if(!d||d.revealed)return;if(!s.fault){d.feedback='Observa primero la respuesta completa del PLC hasta la alarma.';return;}d.attempts++;if(answer===d.id){d.solved=d.revealed=true;d.feedback='Correcto. '+cases.find(c=>c.id===d.id).explain;}else d.feedback='Todavía no. Compara presión, posición alcanzada y señal de extremo antes del fallo. Puedes pedir una pista.';}
export function diagnosticHidden(s){return !!s.diagnostic&&!s.diagnostic.revealed;}
export function createDiagnosticPanel(root,{onStart,onExit,onRefresh}){const el=document.createElement('section');el.className='hmi-diagnostic';el.innerHTML=`<span class="eyebrow">MISIÓN / DIAGNÓSTICO</span><h3>Encuentra el fallo oculto</h3><p>Inicia un banco nuevo en automático. Aparecerá un único fallo sorpresa durante el avance. Observa la HMI, las tendencias y el ladder; la simulación se pausa al producirse la alarma para conservar las pruebas.</p><div class="hmi-actions"><button id="diagStart">Nuevo reto sorpresa</button><button id="diagHint">Pedir pista</button><button id="diagReveal">Ver solución</button><button id="diagExit">Salir y restaurar banco</button></div><p id="diagStatus" role="status"></p><p id="diagHintText"></p><label>Tu diagnóstico <select id="diagAnswer"><option value="">Selecciona una hipótesis</option>${cases.map(c=>`<option value="${c.id}">${c.label}</option>`).join('')}</select></label> <button id="diagCheck">Comprobar</button><p id="diagFeedback" role="status"></p><p>La posición es una observación del simulador, no una entrada analógica del PLC. Un timeout por sí solo no identifica un atasco ni un cable desconectado. Nuevo reto y Salir reinician el banco, el contador y las trazas.</p>`;root.prepend(el);const q=id=>el.querySelector('#'+id);let current;
 q('diagStart').onclick=()=>{q('diagAnswer').value='';onStart();};q('diagExit').onclick=onExit;q('diagHint').onclick=()=>{if(current?.diagnostic)current.diagnostic.hints=Math.min(3,current.diagnostic.hints+1);onRefresh();};q('diagCheck').onclick=()=>{if(current)answerDiagnostic(current,q('diagAnswer').value);onRefresh();};q('diagReveal').onclick=()=>{const d=current?.diagnostic;if(d&&current.fault){d.revealed=true;d.feedback='Solución: '+cases.find(c=>c.id===d.id).label+'. '+cases.find(c=>c.id===d.id).explain;}onRefresh();};
 return {update(s,disabled){current=s;const d=s.diagnostic;for(const id of ['diagHint','diagCheck','diagAnswer'])q(id).disabled=disabled||!d||d.revealed;q('diagReveal').disabled=disabled||!d||d.revealed||!s.fault;q('diagStart').disabled=disabled;q('diagExit').disabled=disabled||!d;q('diagStatus').textContent=!d?'Banco libre. Prepara tu siguiente investigación.':d.revealed?(d.solved?'Reto resuelto':'Solución consultada')+' · Intentos: '+d.attempts+' · Pistas: '+d.hints:s.fault?'Alarma registrada. Compara las evidencias y elige una hipótesis.':'Reto activo: observa el ciclo. Los mandos de inyección están ocultos.';q('diagHintText').textContent=!d||!d.hints?'':d.hints===1?'Pista 1: empieza por la presión. Después compara posición, orden de salida y sensor de extremo.':d.hints===2?'Pista 2: '+cases.find(c=>c.id===d.id).hint:'Pista 3: revisa el instante anterior a FALLO. Presión a cero, posición detenida a mitad de carrera o extremo alcanzado sin señal son evidencias distintas.';q('diagFeedback').textContent=d?.feedback||'';}};
}
